const NoMatch = () => <ArchiveScreen
    records={archiveRecords.filter((r) => r.termination?.reason === 'Rejected')}
    defaultFilter="Ghosted" />;

const RestoreRemovesRow = args => {
    const [records, setRecords] = useState(args.records);
    const [calls, setCalls] = useState<string[]>([]);

    return (
        <>
            <ArchiveScreen
                records={records}
                onRestore={(id) => {
                  setCalls((c) => [...c, id]);
                  setRecords((rs) => rs.filter((r) => r.id !== id));
                }} />
            <output data-testid="restore-calls" hidden>
                {calls.join(',')}
            </output>
        </>
    );
};

const RestoreLastRowsMoveFocus = args => {
    const [records, setRecords] = useState(args.records);

    return (
        <ArchiveScreen
            records={records}
            onRestore={(id) => setRecords((rs) => rs.filter((r) => r.id !== id))} />
    );
};

const BriefCounts = () => <ArchiveScreen
    records={Array.from({ length: 37 }, (_, i) => ({
      ...bareRecord,
      id: `generated-${i}`,
      companyName: `Company ${i + 1}`,
      termination: { reason: i < 25 ? 'Rejected' : i < 33 ? 'Ghosted' : 'Withdrawn' },
    }))} />;

const LargeCounts = () => <ArchiveScreen
    records={Array.from({ length: 137 }, (_, i) => ({
      ...bareRecord,
      id: `generated-${i}`,
      companyName: `Company ${i + 1}`,
      termination: { reason: i % 3 === 0 ? 'Rejected' : i % 3 === 1 ? 'Ghosted' : 'Withdrawn' },
    }))} />;

const OpenRowTwinRestoreDisabled = () => <ArchiveScreen
    records={archiveRecords.map((r) => (r.id === richRecord.id ? { ...r, restoreUnavailable: true } : r))}
